from taf.rfrl.admin_cli_checker.admin_cli_command_handler import CommandHandler
from taf.rfrl.admin_cli_checker.comparer import CommandComparer

DEFAULT_COMMAND_LIST = ['get_bts_info',
                        'get_active_alarms',
                        'get_alarm_history']


class AdminCliChecker(object):
    def __init__(self):
        self.admin = CommandHandler()

    def __del__(self):
        self.admin.teardown_admin()

    def get_commands_output_initialize(self, commands=DEFAULT_COMMAND_LIST):
        """ Method is to initialize whole process of command comparison. Take the command output and put it to file in
        directory "commands_response".
        :param commands: List of commands to write their output to the files.
        :return: None.
        """
        self.admin.initialize_all_commands(commands_list=commands)

    def get_commands_output(self, commands=DEFAULT_COMMAND_LIST):
        """ Method is to get command output and write it to the file and to variable.
        :param commands: List of commands to write their output to the files and variable.
        :return: List of dicts:
        [{'command_name1': {'pattern': pattern_command_output1, 'current': current_command_output1},
         {'command_name2': {'pattern': pattern_command_output2, 'current': current_command_output2}]
            For example:
            [{'get_alarm_history':
                {
                    'pattern':
                    {
                        'time': '11:43:34 AM',
                        'requestId': 48408,
                        'requestStatus': 'completed',
                        'requestMessage': [],
                        'errorCode': 0},
                    'current':
                    {
                        'time': '10:34:44 AM',
                        'requestId': 18057,
                        'requestStatus': 'completed',
                        'requestMessage': [], 'errorCode': 0}
                }
            }].
        """
        self.admin.get_all_comands_output(commands_list=commands)
        return self.admin.read_all_outputs_from_file(commands_list=commands)

    def compare_commands_output(self, commands=DEFAULT_COMMAND_LIST):
        """ Method is to compare command outputs and raise ERROR if any change occurs.
        :param commands: List of commands to compare.
        :return: None
        """
        commands_output = self.get_commands_output(commands=commands)
        print(commands_output)
        for command_out in commands_output:
            for command in commands:
                for k, v in command_out.items():
                    compare = CommandComparer(command, v['pattern'], v['current'])
                    compare.compare_commands_result()
